import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    def get_cpu_usage():
        system = platform.system()
        try:
            if system == "Windows":
                output = subprocess.check_output(
                    "wmic cpu get loadpercentage /value",
                    shell=True,
                    stderr=subprocess.DEVNULL
                ).decode("utf-8", errors="ignore")
                for line in output.splitlines():
                    if "LoadPercentage" in line and "=" in line:
                        return float(line.split("=")[1].strip())
            elif system == "Darwin":
                output = subprocess.check_output(
                    "top -l 1 | grep 'CPU usage'",
                    shell=True,
                    stderr=subprocess.DEVNULL
                ).decode("utf-8", errors="ignore")
                parts = output.replace(",", "").split()
                for i, part in enumerate(parts):
                    if part == "idle":
                        idle = float(parts[i - 1].replace("%", ""))
                        return round(100.0 - idle, 2)
            else:
                output = subprocess.check_output(
                    "top -bn1 | grep 'Cpu(s)'",
                    shell=True,
                    stderr=subprocess.DEVNULL
                ).decode("utf-8", errors="ignore")
                parts = output.replace(",", " ").split()
                for i, part in enumerate(parts):
                    if part in ("id", "id,"):
                        idle = float(parts[i - 1])
                        return round(100.0 - idle, 2)
        except Exception:
            return 0.0
        return 0.0

    records = []
    start_time = time.time()

    while time.time() - start_time < duration:
        records.append({
            "timestamp": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime()),
            "cpu_usage": get_cpu_usage()
        })
        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w") as logfile:
            json.dump(records, logfile)
        return LOGFILE_PATH
    except IOError:
        return None

