import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    failed_files = []

    if not os.path.isdir(src_folder):
        return {
            'success': False,
            'message': 'Source folder does not exist or is not a directory.',
            'failed_files': []
        }

    try:
        os.makedirs(dst_folder, exist_ok=True)
    except Exception:
        return {
            'success': False,
            'message': 'Failed to create or access destination folder.',
            'failed_files': []
        }

    files = [f for f in glob(os.path.join(src_folder, '*')) if os.path.isfile(f)]
    processes = []

    for file_path in files:
        try:
            process = subprocess.Popen(['gzip', '-f', file_path])
            processes.append((file_path, process))
        except Exception:
            failed_files.append(os.path.basename(file_path))

    for file_path, process in processes:
        try:
            return_code = process.wait()
            gz_file = file_path + '.gz'
            if return_code != 0 or not os.path.exists(gz_file):
                failed_files.append(os.path.basename(file_path))
                continue
            shutil.move(gz_file, os.path.join(dst_folder, os.path.basename(gz_file)))
        except Exception:
            failed_files.append(os.path.basename(file_path))

    success = len(failed_files) == 0

    return {
        'success': success,
        'message': 'All files were compressed and moved successfully.' if success else 'Some files failed to compress or move.',
        'failed_files': failed_files
    }

