import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")

    process = subprocess.Popen(script_path, shell=True)
    cpu_usage = 0.0
    memory_usage = 0
    last_memory = {}

    start_time = time.time()

    try:
        ps_process = psutil.Process(process.pid)
        ps_process.cpu_percent(interval=None)

        while True:
            if process.poll() is not None:
                break

            if time.time() - start_time >= timeout:
                break

            try:
                processes = [ps_process] + ps_process.children(recursive=True)
                time.sleep(0.1)

                for proc in processes:
                    try:
                        if proc.status() == psutil.STATUS_ZOMBIE:
                            continue

                        cpu_usage += proc.cpu_percent(interval=None)
                        rss = proc.memory_info().rss
                        pid = proc.pid

                        previous_rss = last_memory.get(pid, 0)
                        if rss > previous_rss:
                            memory_usage += rss - previous_rss
                        last_memory[pid] = rss

                    except (psutil.NoSuchProcess, psutil.ZombieProcess, psutil.AccessDenied):
                        continue

            except (psutil.NoSuchProcess, psutil.ZombieProcess, psutil.AccessDenied):
                break

        if process.poll() is None:
            try:
                process.terminate()
                process.wait(timeout=1)
            except Exception:
                try:
                    process.kill()
                except Exception:
                    pass

    except (psutil.NoSuchProcess, psutil.ZombieProcess, psutil.AccessDenied):
        pass

    return {
        "CPU Usage": cpu_usage,
        "Memory Usage": memory_usage
    }

